import math
import random
import unittest
from solution import closest_pair


def brute(points):
    best = None
    pair = None
    for i, a in enumerate(points):
        for b in points[i + 1:]:
            d = math.hypot(a[0] - b[0], a[1] - b[1])
            if best is None or d < best:
                best, pair = d, (a, b)
    return best, pair


class TestClosestPair(unittest.TestCase):
    def test_duplicates(self):
        distance, a, b = closest_pair([(0, 0), (4, 5), (0, 0)])
        self.assertEqual(distance, 0)
        self.assertEqual(a, b)

    def test_random_matches_oracle(self):
        rng = random.Random(7)
        for size in range(2, 35):
            points = [(rng.randrange(-50, 51), rng.randrange(-50, 51)) for _ in range(size)]
            expected, _ = brute(points)
            actual, a, b = closest_pair(points)
            self.assertTrue(math.isclose(actual, expected))
            self.assertIn(a, points)
            self.assertIn(b, points)


if __name__ == '__main__':
    unittest.main()
